// Agoda — minimum price with discount coupons (reconstructed from reported titles).
public static class Coupons {
    // Each coupon takes a percentage off ONE item; each item takes at most one coupon. Minimum total.
    // Rearrangement inequality: biggest discounts on the most expensive items.
    public static decimal MinTotalPercent(decimal[] prices, int[] percentOff) {
        if (prices == null || prices.Length == 0) return 0m;
        var p = prices.OrderByDescending(x => x).ToArray();
        var c = (percentOff ?? Array.Empty<int>()).OrderByDescending(x => x).ToArray();
        decimal total = 0;
        for (int i = 0; i < p.Length; i++) {
            if (p[i] < 0) throw new ArgumentOutOfRangeException(nameof(prices));
            int off = i < c.Length ? c[i] : 0;
            if (off < 0 || off > 100) throw new ArgumentOutOfRangeException(nameof(percentOff));
            total += p[i] * (100 - off) / 100m;
        }
        return total;
    }

    // Flat coupons with a minimum price: coupon j takes amount[j] off one item whose price >= minPrice[j]
    // (amount <= minPrice, so a price never goes negative). Maximise the total discount; return the minimum total.
    // Sweep items cheapest first; every coupon whose minimum the item meets becomes available; take the largest.
    public static decimal MinTotalFlat(decimal[] prices, decimal[] minPrice, decimal[] amount) {
        if (prices == null || prices.Length == 0) return 0m;
        minPrice ??= Array.Empty<decimal>(); amount ??= Array.Empty<decimal>();
        if (minPrice.Length != amount.Length) throw new ArgumentException("coupon arrays differ in length");
        for (int j = 0; j < amount.Length; j++)
            if (amount[j] < 0 || amount[j] > minPrice[j]) throw new ArgumentOutOfRangeException(nameof(amount), "a coupon must not exceed its minimum price");
        var items = prices.OrderBy(x => x).ToArray();
        var order = Enumerable.Range(0, minPrice.Length).OrderBy(j => minPrice[j]).ToArray();
        var heap = new PriorityQueue<decimal, decimal>(Comparer<decimal>.Create((a, b) => b.CompareTo(a)));   // max-heap
        decimal total = 0; int k = 0;
        foreach (var price in items) {
            while (k < order.Length && minPrice[order[k]] <= price) { heap.Enqueue(amount[order[k]], amount[order[k]]); k++; }
            total += price - (heap.Count > 0 ? heap.Dequeue() : 0m);
        }
        return total;
    }
}
